import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip (in background) 
    and move the compressed files to a destination folder.

    Parameters:
    - src_folder (str): Path to the source folder containing files to compress.
    - dst_folder (str): Path to the destination folder for compressed files.

    Returns:
    - dict: A dictionary with keys:
        'success': Boolean indicating if all files were processed successfully.
        'message': Descriptive message about the operation result.
        'failed_files': List of filenames that failed to compress or move.
    """
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist.",
            'failed_files': []
        }
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except OSError as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder '{dst_folder}': {e}",
                'failed_files': []
            }
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isdir(file_path):
            continue
        try:
            # Compress using gzip in background
            subprocess.run(['gzip', '-c', file_path], 
                           stdout=open(file_path + '.gz', 'wb'), 
                           stderr=subprocess.DEVNULL, 
                           check=True)
            # Move the compressed file
            shutil.move(file_path + '.gz', 
                        os.path.join(dst_folder, os.path.basename(file_path) + '.gz'))
        except (subprocess.CalledProcessError, OSError, shutil.Error) as e:
            failed_files.append(os.path.basename(file_path))
            # Clean up any leftover .gz file in source folder
            gz_path = file_path + '.gz'
            if os.path.exists(gz_path):
                try:
                    os.remove(gz_path)
                except OSError:
                    pass
    success = len(failed_files) == 0
    if success:
        message = f"All files from '{src_folder}' were successfully compressed and moved to '{dst_folder}'."
    else:
        message = f"Compression and move completed with {len(failed_files)} failures."
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the source folder using gzip and move the compressed files to the destination folder.
    The operation runs in the background (non-blocking) and returns a dictionary with the results.

    Parameters:
    src_folder (str): Path to the source folder containing files to compress.
    dst_folder (str): Path to the destination folder for compressed files.

    Returns:
    dict: A dictionary containing:
        - 'success' (bool): True if all files were processed successfully, False otherwise.
        - 'message' (str): Descriptive message about the operation result.
        - 'failed_files' (list): List of filenames that failed to compress or move.
    """
    if not os.path.exists(src_folder):
        return {
            'success': False,
            'message': f'Source folder does not exist: {src_folder}',
            'failed_files': []
        }
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder, exist_ok=True)
        except Exception as e:
            return {
                'success': False,
                'message': f'Failed to create destination folder {dst_folder}: {str(e)}',
                'failed_files': []
            }
    files = glob(os.path.join(src_folder, '*'))
    failed_files = []
    for file_path in files:
        if os.path.isdir(file_path):
            continue
        try:
            # Compress the file using gzip in background
            process = subprocess.Popen(['gzip', '-c', file_path], stdout=subprocess.PIPE)
            compressed_data, _ = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, 'gzip')
            # Write compressed data to destination
            dst_file = os.path.join(dst_folder, os.path.basename(file_path) + '.gz')
            with open(dst_file, 'wb') as f:
                f.write(compressed_data)
        except Exception as e:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    if success:
        message = f'All files from {src_folder} compressed and moved to {dst_folder} successfully.'
    else:
        message = f'Compression completed with {len(failed_files)} file(s) failed.'
    return {
        'success': success,
        'message': message,
        'failed_files': failed_files
    }

import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    """
    Compress all files in the specified source folder using gzip and move the compressed files to a destination folder.
    The operation runs in the background and returns a dictionary with the operation results.

    Parameters:
    src_folder (str): Source folder containing files to compress
    dst_folder (str): Destination folder for compressed files

    Returns:
    dict: Dictionary containing:
        - 'success': Boolean indicating if all files were processed successfully
        - 'message': Descriptive message about the operation result
        - 'failed_files': List of filenames that failed to compress or move
    """
    failed_files = []
    success = True

    # Validate source folder exists
    if not os.path.exists(src_folder) or not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': f"Source folder '{src_folder}' does not exist or is not a directory",
            'failed_files': []
        }

    # Create destination folder if it doesn't exist
    if not os.path.exists(dst_folder):
        try:
            os.makedirs(dst_folder)
        except Exception as e:
            return {
                'success': False,
                'message': f"Failed to create destination folder: {str(e)}",
                'failed_files': []
            }

    # Get all files in source folder (excluding subdirectories)
    try:
        files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    except Exception as e:
        return {
            'success': False,
            'message': f"Failed to list files in source folder: {str(e)}",
            'failed_files': []
        }

    # Process each file
    for filename in files:
        src_path = os.path.join(src_folder, filename)
        compressed_filename = filename + '.gz'
        dst_path = os.path.join(dst_folder, compressed_filename)

        try:
            # Compress file using gzip in background
            # Using nohup to keep process running in background even if parent terminates
            subprocess.Popen(
                ['gzip', '-c', src_path],
                stdout=open(dst_path, 'wb'),
                stderr=subprocess.DEVNULL
            )

        except Exception as e:
            failed_files.append(filename)
            success = False

    # Determine result message
    if not files:
        message = f"No files found in source folder '{src_folder}'"
    elif success and not failed_files:
        message = f"Successfully started compression of {len(files)} file(s) from '{src_folder}' to '{dst_folder}'"
    else:
        message = f"Started compression of {len(files)} file(s) with {len(failed_files)} failure(s)"

    return {
        'success': success and len(failed_files) == 0,
        'message': message,
        'failed_files': failed_files
    }
